# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZI BOZAN DURUMLAR VE SEHİV (YANILMA) SECDESİ</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Namazı Bozan Başlıca Durumlar</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" fill="#7f1d1d">• Namaz kılarken konuşmak veya selam alıp vermek</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" fill="#7f1d1d">• Namaz esnasında bir şey yemek veya içmek</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" fill="#7f1d1d">• Kendi duyacağı kadar gülmek (başkası duyarsa abdest de bozulur)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="12" fill="#7f1d1d">• Kıbleden göğsünü çevirmek veya abdestin bozulması</text>\n  <text x="180" y="194" text-anchor="middle" font-size="12" fill="#7f1d1d">• Namazın farzlarından birini terk etmek</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Bozulan namaz yeniden kılınır (iade edilir).</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sehiv Secdesi (Yanılma Secdesi)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Ne Zaman Yapılır?</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#1e40af">Namazda bir farzın geciktirilmesi veya bir vacibin</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#1e40af">unutularak terk edilmesi / geciktirilmesi durumunda.</text>\n  <text x="520" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Nasıl Yapılır?</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" fill="#0f172a">1. Son oturuşta Tahiyyat okunur, sağa selam verilir.</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#0f172a">2. Tekbirle peş peşe iki secde yapılır ve tekrar oturulur.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#0f172a">3. Tahiyyat, Salli-Barik, Rabbena okunup iki yana selam verilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEMAATLE KILINAN NAMAZLAR: CUMA, BAYRAM, TERAVİH VE CENAZE</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="97" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cuma Namazı</text>\n  <text x="97" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hüküm: Farz-ı Ayn</text>\n  <text x="97" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Cuma günü öğle vakti</text>\n  <text x="97" y="140" text-anchor="middle" font-size="11" fill="#14532d">• 4 ilk sünnet + 2 farz</text>\n  <text x="97" y="158" text-anchor="middle" font-size="11" fill="#14532d">+ 4 son sünnet (10 rekât)</text>\n  <text x="97" y="180" text-anchor="middle" font-size="11" fill="#14532d">• Farzdan önce hutbe</text>\n  <text x="97" y="198" text-anchor="middle" font-size="11" fill="#14532d">okunması şarttır.</text>\n\n  <rect x="190" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="267" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bayram Namazı</text>\n  <text x="267" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Hüküm: Vacip</text>\n  <text x="267" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">• Ramazan ve Kurban</text>\n  <text x="267" y="140" text-anchor="middle" font-size="11" fill="#1e3a8a">• 2 rekâttır, cemaatle</text>\n  <text x="267" y="158" text-anchor="middle" font-size="11" fill="#1e3a8a">ve ilave tekbirlerle kılınır</text>\n  <text x="267" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">• Hutbe namazdan</text>\n  <text x="267" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">sonra okunur (sünnettir).</text>\n\n  <rect x="360" y="48" width="155" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="437" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Teravih Namazı</text>\n  <text x="437" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Hüküm: Sünnet</text>\n  <text x="437" y="120" text-anchor="middle" font-size="11" fill="#78350f">• Ramazan ayı boyunca</text>\n  <text x="437" y="140" text-anchor="middle" font-size="11" fill="#78350f">• Yatsı namazından sonra,</text>\n  <text x="437" y="158" text-anchor="middle" font-size="11" fill="#78350f">vitir namazından önce</text>\n  <text x="437" y="180" text-anchor="middle" font-size="11" fill="#78350f">• Genellikle 20 rekât</text>\n  <text x="437" y="198" text-anchor="middle" font-size="11" fill="#78350f">(2 veya 4 rekâtta selamla)</text>\n\n  <rect x="530" y="48" width="150" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="605" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Cenaze Namazı</text>\n  <text x="605" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Hüküm: Farz-ı Kifaye</text>\n  <text x="605" y="120" text-anchor="middle" font-size="11" fill="#581c87">• Vefat eden mümin</text>\n  <text x="605" y="138" text-anchor="middle" font-size="11" fill="#581c87">kardeşler için dua niteliği</text>\n  <text x="605" y="158" text-anchor="middle" font-size="11" fill="#581c87">• Rükû ve secdesi yoktur</text>\n  <text x="605" y="180" text-anchor="middle" font-size="11" fill="#581c87">• Ayakta (kıyamda)</text>\n  <text x="605" y="198" text-anchor="middle" font-size="11" fill="#581c87">4 tekbir ile kılınır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZ İBADETİNİN BİREYE VE TOPLUMA KAZANDIRDIKLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bireysel ve Ahlaki Kazanımlar</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" fill="#1e3a8a">• Allah (c.c.) ile bağı güçlendirir ve iç huzuru verir</text>\n  <text x="180" y="126" text-anchor="middle" font-size="12" fill="#1e3a8a">• İnsanı kötülüklerden ve çirkin davranışlardan korur</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" fill="#1e3a8a">• Günde 5 vakit ile zamanı planlama bilinci kazandırır</text>\n  <text x="180" y="178" text-anchor="middle" font-size="12" fill="#1e3a8a">• Abdest ve temizlik şartlarıyla beden/çevre temizliği sağlar</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">«Şüphesiz namaz, insanı hayasızlıktan ve kötülükten alıkoyar.» (Ankebût, 45)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Toplumsal Kazanımlar ve Kardeşlik</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" fill="#14532d">• Camide aynı safta omuz omuza eşitlik duygusu yaşatır</text>\n  <text x="520" y="126" text-anchor="middle" font-size="12" fill="#14532d">• Komşular ve müminler arasında tanışmayı artırır</text>\n  <text x="520" y="152" text-anchor="middle" font-size="12" fill="#14532d">• Sevinçleri (bayram) ve hüzünleri (cenaze) paylaştırır</text>\n  <text x="520" y="178" text-anchor="middle" font-size="12" fill="#14532d">• Toplumsal birlik, beraberlik ve yardımlaşmayı pekiştirir</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Cemaatle namaz bireysel namazdan 27 derece daha faziletlidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
